          `UPDATE dataset_release_job SET release_id=$2::uuid,events_processed=$3,bytes_written=$4,page_number=$5,lease_owner=NULL,lease_expires_at=NULL,attempt_storage_key=NULL WHERE job_id=$1::uuid`,
