import { describe, expect, it } from 'vitest';

import {
  DATASET_RELEASE_FIELDS,
  datasetReleaseCollectionResponseSchema,
  datasetReleaseJobResponseSchema,
} from '../dataset-releases';

const release = {
  releaseId: 'ba756ad4-4b1e-4b80-81f2-09a66ed6c854',
  version: '2026.09.14v1',
  createdAt: '2026-09-14T10:18:37.161Z',
  formatVersion: '1.0',
  scope: 'published-accepted-deliveries',
  eventCount: 3_207_110,
  checksum: '46af530f0320361aec114769cb54cefd6bf4acd3fc8610c1567c3b7656d1fe25',
  fields: [...DATASET_RELEASE_FIELDS],
};

describe('dataset release contracts', () => {
  it('accepts the completed production-scale release response with an RFC 3339 timestamp', () => {
    expect(datasetReleaseCollectionResponseSchema.parse({ data: [release] })).toEqual({
      data: [release],
    });
  });

  it('accepts a pending asynchronous job whose release is null', () => {
    const job = {
      jobId: '340824be-b274-47d4-b624-97e874f3ee50',
      version: release.version,
      status: 'pending',
      eventsProcessed: 0,
      bytesWritten: 0,
      pageNumber: 0,
      createdAt: '2026-09-14T10:05:26.034Z',
      startedAt: null,
      completedAt: null,
      failureCode: null,
      failureMessage: null,
      release: null,
    };

    expect(datasetReleaseJobResponseSchema.parse({ data: job })).toEqual({ data: job });
  });

  it('rejects PostgreSQL display timestamps because the API contract requires RFC 3339', () => {
    const result = datasetReleaseCollectionResponseSchema.safeParse({
      data: [{ ...release, createdAt: '2026-09-14 10:18:37.161956+00' }],
    });

    expect(result.success).toBe(false);
    if (!result.success) expect(result.error.issues[0]?.path).toEqual(['data', 0, 'createdAt']);
  });
});

import { Readable } from 'node:stream';

import { describe, expect, test, vi } from 'vitest';

import type { DatasetReleaseRepository } from '../../src/modules/dataset-releases/dataset-release.repository';
import { createDatasetReleaseService } from '../../src/modules/dataset-releases/dataset-release.service';
import { FakeObjectStore } from '../../src/modules/object-storage/fake-object-store';

const snapshot = {
  releaseId: '01234567-89ab-cdef-0123-456789abcdef',
  version: '2026.09.1',
  createdAt: '2026-09-14T10:00:00.000Z',
  eventCount: 3,
  checksum: 'a'.repeat(64),
};
const job = {
  jobId: '11111111-1111-4111-8111-111111111111',
  version: snapshot.version,
  state: 'queued' as const,
  eventsProcessed: 0,
  bytesWritten: 0,
  pageNumber: 0,
  createdAt: snapshot.createdAt,
  startedAt: null,
  completedAt: null,
  failureCode: null,
  failureMessage: null,
  release: null,
};

function repository(): DatasetReleaseRepository {
  return {
    loadPublishedEventPage: vi.fn(),
    requestGeneration: vi.fn(async () => ({ release: null, job })),
    findJob: vi.fn(async () => job),
    list: vi.fn(async () => [snapshot]),
    findByVersion: vi.fn(async () => snapshot),
    findArtifactReferenceByVersion: vi.fn(async () => ({
      storageKey: 'artifact.json',
      legacyArtifactText: null,
      storageLocation: 'release',
    })),
  };
}

describe('dataset release service', () => {
  test('queues generation without reading events or writing the artifact in the request', async () => {
    const releases = repository();
    const store = new FakeObjectStore();
    const service = createDatasetReleaseService(releases, {
      deploymentEnvironment: 'local',
      storageProvider: 'filesystem',
